// ProvidersSchema returns the schema of ai_providers.
func ProvidersSchema() *schema.Table { return &providersTable }

// As returns a handle that references ai_providers under its own alias.
func (t *ProvidersTable) As(alias string) *ProvidersTable {
	return keel.Alias(t.Ref, alias, BuildProviders)
}

// Get returns the ai_providers row with the given key, or keel.ErrNotFound.
func (t *ProvidersTable) Get(ctx context.Context, db *keel.DB, key pulid.ID) (*aiprovider.Provider, error) {
	return t.Where(t.ID.Eq(key)).One(ctx, db)
}

func newProvider() unsafe.Pointer { return unsafe.Pointer(new(aiprovider.Provider)) }

func newNProvider(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]aiprovider.Provider, n)))
}

